const STREAK_NETWORK_DELAY_MS = 300;

function streakDelay<T>(value: T, ms: number = STREAK_NETWORK_DELAY_MS): Promise<T> {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

