// ============================================================================
// FILE: services/ChallengeService.ts
// ============================================================================
// ============================================================================
// Spacia — ChallengeService
// Mimics `GET /api/challenge/today` and `POST /api/challenge/:id/start`.
// ============================================================================


const CHALLENGE_NETWORK_DELAY_MS = 300;

function challengeDelay<T>(value: T, ms: number = CHALLENGE_NETWORK_DELAY_MS): Promise<T> {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

// In-memory copy so "starting" a challenge can mutate state between calls,
// the same way a real backend session would.
let challengeState: Challenge = { ...mockDailyChallenge };

export const ChallengeService = {
  /** GET /api/challenge/today */
  async getTodayChallenge(): Promise<Challenge> {
    return challengeDelay({ ...challengeState });
  },

  /** POST /api/challenge/:id/start — nudges progress forward to simulate starting a session. */
  async startChallenge(id: string): Promise<Challenge> {
    if (challengeState.id === id && !challengeState.completed) {
      const nextProgress = Math.min(
        challengeState.progress + 5,
        challengeState.target
      );
      challengeState = {
        ...challengeState,
        progress: nextProgress,
        completed: nextProgress >= challengeState.target,
      };
    }
    return challengeDelay({ ...challengeState });
  },
};

// ============================================================================
// FILE: hooks/useStreak.ts
// ============================================================================
// ============================================================================
// Spacia — useStreak
// Loads streak info via StreakService. The UI never knows whether this data
// comes from mock services or a real backend.
// ============================================================================


export function useStreak(): AsyncResource<StreakInfo> {
  const [data, setData] = useState<StreakInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (isRefresh: boolean) => {
    try {
      isRefresh ? setRefreshing(true) : setLoading(true);
      setError(null);
      const result = await StreakService.getStreak();
      setData(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load streak.");
    } finally {
      isRefresh ? setRefreshing(false) : setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(false);
  }, [load]);

  const refresh = useCallback(async () => {
    await load(true);
  }, [load]);

  return { data, loading, refreshing, error, refresh };
}

// ============================================================================
// FILE: hooks/useDailyGoal.ts
// ============================================================================
// ============================================================================
// Spacia — useDailyGoal
// Loads today's goal via StreakService and exposes derived progress values.
// ============================================================================


interface UseDailyGoalResult extends AsyncResource<DailyGoal> {
  percent: number;
  remaining: number;
  isComplete: boolean;
  message: string;
}

export function useDailyGoal(): UseDailyGoalResult {
  const [data, setData] = useState<DailyGoal | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (isRefresh: boolean) => {
    try {
      isRefresh ? setRefreshing(true) : setLoading(true);
      setError(null);
      const result = await StreakService.getDailyGoal();
      setData(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load daily goal.");
    } finally {
      isRefresh ? setRefreshing(false) : setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(false);
  }, [load]);

  const refresh = useCallback(async () => {
    await load(true);
  }, [load]);

  const progress = useMemo(
    () => (data ? computeDailyGoalProgress(data) : { percent: 0, remaining: 0, isComplete: false }),
    [data]
  );

  const message = useMemo(() => dailyGoalMessage(progress), [progress]);

  return { data, loading, refreshing, error, refresh, ...progress, message };
}

// ============================================================================
// FILE: hooks/useStatistics.ts
// ============================================================================
// ============================================================================
// Spacia — useStatistics
// ============================================================================


export function useStatistics(): AsyncResource<Statistics> {
  const [data, setData] = useState<Statistics | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (isRefresh: boolean) => {
    try {
      isRefresh ? setRefreshing(true) : setLoading(true);
      setError(null);
      const result = await StatisticsService.getStatistics();
      setData(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load statistics.");
    } finally {
      isRefresh ? setRefreshing(false) : setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(false);
  }, [load]);

  const refresh = useCallback(async () => {
    await load(true);
  }, [load]);

  return { data, loading, refreshing, error, refresh };
}

