interface ChallengeCardProps {
  challenge: Challenge;
  starting: boolean;
  onStart: () => void;
}

export function ChallengeCard({ challenge, starting, onStart }: ChallengeCardProps) {
  return (
    <View style={challengeCardStyles.card}>
      <View style={challengeCardStyles.topRow}>
        <View style={challengeCardStyles.iconWrap}>
          <MaterialCommunityIcons name="sword-cross" size={20} color={colors.xpGold} />
        </View>
        <View style={challengeCardStyles.rewardPill}>
          <MaterialCommunityIcons name="star-four-points" size={12} color={colors.xpGold} />
          <Text style={challengeCardStyles.rewardText}>{challenge.rewardXP} XP</Text>
        </View>
      </View>

      <Text style={challengeCardStyles.title}>{challenge.title}</Text>
      <Text style={challengeCardStyles.description}>{challenge.description}</Text>

      <Text style={challengeCardStyles.progressText}>
        {challenge.progress}/{challenge.target} completed
      </Text>

      <Pressable
        onPress={onStart}
        disabled={challenge.completed || starting}
        style={({ pressed }) => [
          challengeCardStyles.button,
          challenge.completed && challengeCardStyles.buttonCompleted,
          pressed && !challenge.completed && challengeCardStyles.buttonPressed,
        ]}
      >
        {starting ? (
          <ActivityIndicator color={colors.textInverse} size="small" />
        ) : (
          <>
            <MaterialCommunityIcons
              name={challenge.completed ? "check-bold" : "play"}
              size={16}
              color={colors.textInverse}
            />
            <Text style={challengeCardStyles.buttonText}>
              {challenge.completed ? "Challenge Complete" : "Start Challenge"}
            </Text>
          </>
        )}
      </Pressable>
    </View>
  );
}

